"use client"

import { mergeProps, renderElement, type PartProps } from "@ui-sdk/react/primitive"

import { hashPrefixAttribute, isHashRoute, useFastLink, type FastLinkOptions } from "@/components/ui/use-fast-link"

type FastLinkRegionProps = PartProps<"div"> &
  FastLinkOptions & {
    /**
     * The start of a hash route's `href` (default `"#/"`), for every link inside, `Link`s included: such a link
     * follows on press, while other `#…` hrefs are in-page anchors and stay native. `false` makes every `#…` href
     * an anchor. Sets `data-fast-link-hash-prefix`, which also works on any element, `<body>` for the whole app.
     */
    hashPrefix?: string | false
  }

/** Fast links for plain anchors in prose or rendered HTML; `Link` already has them. */
function FastLinkRegion({ enabled, onFollow, hashPrefix, render, ...props }: FastLinkRegionProps) {
  const ref = useFastLink<HTMLDivElement>({ enabled, onFollow })
  const prefix = hashPrefix === undefined ? undefined : hashPrefix || ""
  return renderElement(
    "div",
    mergeProps({ "data-slot": "fast-link-region", [hashPrefixAttribute]: prefix, ref }, props),
    render,
  )
}

export { FastLinkRegion, hashPrefixAttribute, isHashRoute, useFastLink }
export type { FastLinkOptions, FastLinkRegionProps }

import { definePrimitive, dispatch, type ChangeDetails } from "@ui-sdk/core"

type LinkFollowDetails = ChangeDetails<"follow">

type LinkOptions = {
  href?: string
  onFollow?: (href: string, details: LinkFollowDetails) => void
}

function isPlainClick(event: MouseEvent) {
  return event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey
}

/** A click with a modifier or another button on a link inside the target, which the browser handles natively. */
function isModifiedLinkPress(event: Event | undefined) {
  return (
    event instanceof MouseEvent &&
    !isPlainClick(event) &&
    event.target instanceof Element &&
    event.target.closest("a[href]") !== null
  )
}

// UI SDK ships no link part, so a link is invisible to agents unless the app takes over following it. With
// `onFollow` the app decides what following means (a router push, a confirmation), for people and agents alike.
const link = definePrimitive({
  name: "link",
  options: { href: "string", onFollow: "callback" },
  state: (options: LinkOptions) => ({ value: options.href ?? "" }),
  sync: (options) => ({ value: options.href ?? "" }),
  api: (context) => ({
    follow(event?: Event) {
      const { href = "" } = context.options()
      return !dispatch(context, "onFollow", href, { reason: "follow", event })
    },
  }),
  slots: (slot) => ({
    root: slot({
      on: {
        click: (event, { api }) => {
          const mouse = event as MouseEvent
          if (mouse.defaultPrevented || !isPlainClick(mouse)) return
          mouse.preventDefault()
          api.follow(mouse)
        },
      },
    }),
  }),
  agent: { actions: ["follow"] },
})

export { isModifiedLinkPress, isPlainClick, link }
export type { LinkFollowDetails, LinkOptions }

"use client"

import { mergeProps, renderElement, usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { cva } from "class-variance-authority"
import type { AriaAttributes, MouseEvent, ReactNode } from "react"
import { ArrowUpRightIcon } from "lucide-react"

import { useFastLink } from "@/components/ui/fast-link"
import { isPlainClick, link, type LinkOptions } from "@/components/ui/link-primitive"
import { useLinkIntent } from "@/components/ui/use-link-intent"
import { cn } from "@/lib/utils"

type LinkVariant = "inline" | "nav" | "muted" | "standalone" | "plain"

const focusRing =
  "rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"

// `plain` adds nothing, not even the focus ring, so a row or card styled through className keeps its own.
const linkVariants = cva("", {
  variants: {
    variant: {
      inline: "text-link underline decoration-1 underline-offset-2 hover:decoration-2",
      nav: "text-muted-foreground underline-offset-4 transition-colors duration-micro ease-standard hover:text-foreground hover:underline aria-[current]:font-medium aria-[current]:text-foreground",
      muted:
        "text-muted-foreground underline-offset-2 transition-colors duration-micro ease-standard hover:text-foreground hover:underline",
      standalone:
        "touch-target inline-flex items-center gap-inline font-medium text-link underline-offset-4 hover:underline [&_svg]:size-4 [&_svg]:shrink-0",
      plain: "",
    },
  },
  compoundVariants: [{ variant: ["inline", "nav", "muted", "standalone"], class: focusRing }],
  defaultVariants: { variant: "inline" },
})

type LinkProps = Omit<PartProps<"a">, "children"> & {
  children?: ReactNode
  /**
   * `inline` sits in running text (underlined at rest), `nav` and `muted` list links (underlined on hover),
   * `standalone` is a call to action on its own line, `plain` leaves the look to `className` (a card, a row).
   */
  variant?: LinkVariant
  /** Another site: a trailing icon and `rel="noopener noreferrer"`. Opens in the same tab unless `newTab`. */
  external?: boolean
  /** Opens in a new tab (`target="_blank"`) and says so to screen readers with `newTabLabel`. */
  newTab?: boolean
  newTabLabel?: string
  /** Marks the link to the current page (`aria-current="page"`), or pass another `aria-current` token. */
  current?: boolean | Exclude<AriaAttributes["aria-current"], boolean | "true" | "false">
  /**
   * Takes over a plain click (modified clicks keep the browser's behaviour), for client-side routing. It also
   * offers agents a `follow` action that calls it; links without it are invisible to agents.
   */
  onFollow?: LinkOptions["onFollow"]
  /**
   * Routes on the client, for a router's links that agents don't need as actions of their own (a sidebar, a pager):
   * a primary mouse press follows at once, like a fast link, and a plain click or Enter follows too, without a page
   * load. Modified clicks keep the browser's behaviour. With `onFollow` too, `onFollow` wins.
   */
  onNavigate?: (href: string, event: Event) => void
  /**
   * Runs when someone is about to follow the link (a 65 ms hover, focus, a mouse or pen press), to preload the
   * route. It can run more than once for one visit; keep it idempotent.
   */
  onIntent?: (href: string) => void
  /**
   * Follows a same-origin link on mouse press, not release (default `true`): navigation only, as moving away can't
   * cancel it (WCAG 2.5.2). Without `onFollow` it uses `location.assign`, so it is off with `render` or `onClick`,
   * which act on the click. Off for `external`; `data-no-fast-link` on an ancestor turns a region off.
   */
  fast?: boolean
}

function linkProps({
  variant = "inline",
  external = false,
  newTab = false,
  newTabLabel = "(opens in a new tab)",
  current,
  className,
  children,
  rel,
  target,
  ...props
}: Omit<LinkProps, "onFollow" | "onNavigate" | "onIntent" | "render" | "fast">) {
  return {
    "data-slot": "link",
    "data-variant": variant,
    "data-external": external ? "" : undefined,
    "aria-current": current === true ? ("page" as const) : current || undefined,
    rel: external ? ["noopener noreferrer", rel].filter(Boolean).join(" ") : rel,
    target: newTab ? "_blank" : target,
    className: cn(linkVariants({ variant }), className),
    children: (
      <>
        {children}
        {external && (
          <ArrowUpRightIcon
            data-slot="link-external-icon"
            className="ms-px inline-block size-3 shrink-0 align-baseline rtl:-scale-x-100"
          />
        )}
        {newTab && <span className="sr-only"> {newTabLabel}</span>}
      </>
    ),
    ...props,
  }
}

function FollowLink({ onFollow, onNavigate: _router, onIntent, render, fast = true, ...props }: LinkProps) {
  const handle = usePrimitive(link, { href: props.href, onFollow })
  const ref = useFastLink<HTMLAnchorElement>({
    enabled: fast && !props.external,
    onFollow: (_href, { event }) => handle.api.follow(event),
  })
  const intent = useLinkIntent(props.href, onIntent)
  return usePart(handle, "root", {}, { ...mergeProps(linkProps(props), { ref }, intent), render }, "a")
}

// Without `onFollow` or `onNavigate`, a router element or an `onClick` may route or cancel on the click, so a press
// must not navigate first.
function PlainLink({ render, fast = true, onNavigate, onIntent, ...props }: Omit<LinkProps, "onFollow">) {
  const ref = useFastLink<HTMLAnchorElement>({
    enabled: fast && !props.external && !render && (onNavigate !== undefined || !props.onClick),
    onFollow: onNavigate ? (href, { event }) => onNavigate(href, event) : undefined,
  })
  const intent = useLinkIntent(props.href, onIntent)
  const route = onNavigate && {
    onClick: (event: MouseEvent<HTMLAnchorElement>) => {
      const href = event.currentTarget.getAttribute("href")
      if (event.defaultPrevented || !isPlainClick(event.nativeEvent) || href === null) return
      event.preventDefault()
      onNavigate(href, event.nativeEvent)
    },
  }
  return renderElement("a", mergeProps(linkProps(props), { ref }, intent, route ?? {}), render)
}

function Link({ onFollow, ...props }: LinkProps) {
  if (onFollow) return <FollowLink onFollow={onFollow} {...props} />
  return <PlainLink {...props} />
}

export { Link, linkVariants }
export type { LinkProps, LinkVariant }

"use client"

import { createFastLink, type FastLinkIntent } from "@fast-link/core"
import { useEffect, useEffectEvent, useState, type RefCallback } from "react"

type FastLinkOptions = {
  /** `false` leaves every press native. */
  enabled?: boolean
  /** Navigates instead of `location.assign`, for a client-side router. Receives the authored `href`. */
  onFollow?: (href: string, details: { url: URL; anchor: HTMLAnchorElement; event: PointerEvent }) => void
  /**
   * Follows the anchor this ref is on although it has this role, like a command rendered as an anchor (`option`).
   * An anchor with any other role acts as a control and stays native.
   */
  anchorRole?: string
}

const optOut = "[data-no-fast-link]"
const hashPrefixAttribute = "data-fast-link-hash-prefix"
const defaultHashPrefix = "#/"
const nestedControls = "button, input, label, select, summary, textarea, [role~='button' i]"

// @fast-link/core 0.0.2 leaves every `#…` href native, hash routes (`#/inbox`) included, so these presses are
// resolved here with core's eligibility rules. The anchors that own a controller, and the presses already taken,
// are shared by every root, so a Link inside a FastLinkRegion follows once, by its own settings.
const anchorRoots = new WeakMap<Element, number>()
const handledPresses = new WeakSet<Event>()

/**
 * Whether `href` is a hash route rather than an in-page anchor: it starts with the prefix that the closest
 * `data-fast-link-hash-prefix` gives (`"#/"` without one; an empty value means none).
 */
function isHashRoute(anchor: Element, href: string) {
  if (!href.startsWith("#")) return false
  const prefix = anchor.closest(`[${hashPrefixAttribute}]`)?.getAttribute(hashPrefixAttribute) ?? defaultHashPrefix
  return prefix !== "" && href.startsWith(prefix)
}

type PressIntent = FastLinkIntent & { hashRoute: boolean }

// Core follows only anchors without a role (or `link`), so an `anchorRole` root is resolved here, like hash routes.
function pressIntent(event: PointerEvent, root: HTMLElement, anchorRole: string | undefined): PressIntent | null {
  if (event.defaultPrevented || event.button !== 0 || event.pointerType !== "mouse") return null
  if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || handledPresses.has(event)) return null
  const target = event.target instanceof Element ? event.target : null
  const anchor = target?.closest("a")
  if (!target || !anchor || !root.contains(anchor) || (anchor !== root && anchorRoots.has(anchor))) return null
  const role = anchor.getAttribute("role")
  const ownRole = anchor === root && anchorRole !== undefined && role === anchorRole
  const linkTarget = anchor.getAttribute("target")
  if ((role && !ownRole && !/^\s*(?:link)?\s*$/i.test(role)) || (linkTarget && linkTarget !== "_self")) return null
  const control = target.closest(nestedControls)
  if (anchor.hasAttribute("download") || (control && anchor.contains(control))) return null
  const href = anchor.getAttribute("href")
  const view = anchor.ownerDocument.defaultView
  if (!href || !view) return null
  const url = new URL(href, anchor.ownerDocument.baseURI)
  const hashRoute = isHashRoute(anchor, href)
  if (hashRoute) {
    // A `<base>` elsewhere makes `#/x` another document's URL, which the browser loads natively.
    if (url.href.slice(0, url.href.length - url.hash.length) !== view.location.href.split("#")[0]) return null
  } else if (!ownRole || href.startsWith("#") || url.origin !== view.location.origin) return null
  handledPresses.add(event)
  return { anchor, href, url, hashRoute }
}

// Core reads `data-no-fast-link` only between the pressed element and its anchor. Checking the press here, in a
// capture listener added before core's on the same root, lets an ancestor (a region, `<body>`) opt out too.
function attachFastLink(root: HTMLElement, options: () => FastLinkOptions) {
  let press: PointerEvent | undefined
  let pendingPress: HTMLAnchorElement | undefined
  const follow = (intent: FastLinkIntent, hashRoute: boolean) => {
    const { onFollow } = options()
    const view = intent.anchor.ownerDocument.defaultView
    if (onFollow && press) onFollow(intent.href, { url: intent.url, anchor: intent.anchor, event: press })
    else if (hashRoute && view) view.location.hash = intent.url.hash
    else view?.location.assign(intent.url.href)
  }
  const navigate = (intent: FastLinkIntent) => follow(intent, false)
  const onPointerDown = (event: PointerEvent) => {
    press = event
    pendingPress = undefined
    const target = event.target instanceof Element ? event.target : null
    const enabled = options().enabled !== false && !target?.closest(optOut)
    controller.update({ enabled, navigate })
    const intent = enabled ? pressIntent(event, root, options().anchorRole) : null
    if (!intent) return
    pendingPress = intent.anchor
    follow(intent, intent.hashRoute)
  }
  // The click that ends the press would follow the link again (a router's onFollow, the link part's own click).
  const onClick = (event: MouseEvent) => {
    const anchor = pendingPress
    if (!anchor || event.detail === 0 || !(event.target instanceof Node) || !anchor.contains(event.target)) return
    pendingPress = undefined
    event.preventDefault()
  }
  if (root instanceof HTMLAnchorElement) anchorRoots.set(root, (anchorRoots.get(root) ?? 0) + 1)
  root.addEventListener("pointerdown", onPointerDown, { capture: true })
  root.addEventListener("click", onClick, { capture: true })
  const controller = createFastLink(root, { enabled: options().enabled !== false, navigate })
  return () => {
    root.removeEventListener("pointerdown", onPointerDown, { capture: true })
    root.removeEventListener("click", onClick, { capture: true })
    const owners = (anchorRoots.get(root) ?? 1) - 1
    if (owners > 0) anchorRoots.set(root, owners)
    else anchorRoots.delete(root)
    controller.destroy()
  }
}

/**
 * A ref that follows same-origin links on a primary mouse press instead of on release, on the element itself (an
 * anchor) or on the anchors inside it. Keyboard, touch, pen and modified or non-primary presses stay native. A hash
 * route (`#/inbox`) follows too, through `onFollow` or `location.hash`; an in-page anchor (`#section`) stays native.
 */
function useFastLink<T extends HTMLElement>(options: FastLinkOptions = {}): RefCallback<T> {
  const [element, setElement] = useState<T | null>(null)
  const readOptions = useEffectEvent(() => options)
  useEffect(() => (element ? attachFastLink(element, () => readOptions()) : undefined), [element])
  return setElement
}

export { hashPrefixAttribute, isHashRoute, useFastLink }
export type { FastLinkOptions }

"use client"

import { useRef, type FocusEvent, type PointerEvent } from "react"

/** How long a mouse rests on a link before it counts as intent, as instant.page does. */
const hoverDwell = 65

/**
 * Handlers that call `onIntent(href)` when someone is about to follow the link: the mouse rests on it for 65 ms, it
 * takes focus, or a mouse or pen presses it. A touch press doesn't count, since it may start a scroll. It can run
 * more than once for one visit, so a router's preload should be idempotent.
 */
function useLinkIntent(href: string | undefined, onIntent: ((href: string) => void) | undefined) {
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  if (!onIntent || href === undefined) return {}
  const fire = () => {
    clearTimeout(timer.current)
    onIntent(href)
  }
  return {
    onPointerEnter: (event: PointerEvent<HTMLElement>) => {
      if (event.pointerType === "mouse") timer.current = setTimeout(fire, hoverDwell)
    },
    onPointerLeave: () => clearTimeout(timer.current),
    onPointerDown: (event: PointerEvent<HTMLElement>) => {
      if (event.pointerType !== "touch") fire()
    },
    onFocus: (_event: FocusEvent<HTMLElement>) => fire(),
  }
}

export { useLinkIntent }
